	n, m := int(nextInt()), int(nextInt())
	h := make([]int64, n)
	for i := range h {
		h[i] = nextInt()
	}
	total := make([]int64, n+1)
	for i := 0; i < n; i++ {
		total[nextInt()] += h[i]
	}
	// Take whole types, the m largest totals.
	slices.Sort(total)
	var answer int64
	for i := 0; i < m; i++ {
		answer += total[n-i]
	}
	fmt.Println(answer)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
